package security

import (
	"crypto"
	"crypto/rand"
	"crypto/rsa"
	"crypto/sha256"
	"crypto/x509"
	"encoding/base64"
	"encoding/pem"
	"errors"
	"fmt"
	"os"
)

// RSASigner signs over-the-air update manifests with Expo's
// "rsa-v1_5-sha256" code signing algorithm. The private key is the one
// generated by `make ota-keys` (`expo-updates codesigning:generate`); the
// app embeds the matching certificate and rejects anything else. Implements
// ports.ManifestSigner.
type RSASigner struct {
	key   *rsa.PrivateKey
	keyID string
}

// LoadRSASigner reads a PEM private key (PKCS#8 or PKCS#1). Fails fast on a
// missing or malformed key rather than at the first update check.
func LoadRSASigner(path, keyID string) (*RSASigner, error) {
	raw, err := os.ReadFile(path)
	if err != nil {
		return nil, fmt.Errorf("read code signing key: %w", err)
	}
	block, _ := pem.Decode(raw)
	if block == nil {
		return nil, errors.New("code signing key: no PEM block found")
	}

	var key *rsa.PrivateKey
	if parsed, err := x509.ParsePKCS8PrivateKey(block.Bytes); err == nil {
		rsaKey, ok := parsed.(*rsa.PrivateKey)
		if !ok {
			return nil, errors.New("code signing key: not an RSA key")
		}
		key = rsaKey
	} else if rsaKey, err := x509.ParsePKCS1PrivateKey(block.Bytes); err == nil {
		key = rsaKey
	} else {
		return nil, errors.New("code signing key: unsupported PEM (want an RSA PKCS#8 or PKCS#1 private key)")
	}
	return &RSASigner{key: key, keyID: keyID}, nil
}

func (s *RSASigner) Sign(data []byte) (string, error) {
	digest := sha256.Sum256(data)
	sig, err := rsa.SignPKCS1v15(rand.Reader, s.key, crypto.SHA256, digest[:])
	if err != nil {
		return "", err
	}
	return base64.StdEncoding.EncodeToString(sig), nil
}

func (s *RSASigner) KeyID() string { return s.keyID }
